namespace PersonalExpenseManager.Application.RecurringTransactions;

// The recurring transaction engine: generates due Transaction rows from active
// RecurringTransaction templates across all users. Not user-scoped — this runs as
// a system-wide sweep (see Infrastructure.Services.RecurringTransactionProcessingService),
// not behind an authenticated per-user endpoint.
public interface IRecurringTransactionProcessor
{
    // Returns the number of Transaction rows generated by this run.
    Task<int> ProcessDueAsync(CancellationToken cancellationToken = default);
}
